"""Table 1 (width, coverage with Wilson CI, paired ratio vs PPI++), Table 2 (E5 constructions),
Table 3 (E6 T2 arms) and the full appendix grid, as booktabs LaTeX fragments in tables/."""
import sys
import numpy as np
import pandas as pd
import style, schema, captions
from common import CFG, nice, headline, primary

NOM = CFG["nominal"]


def esc(s):
    return str(s).replace("_", "\\_").replace("&", "\\&").replace("%", "\\%")


def fnum(x, d=3):
    return "--" if pd.isna(x) else f"{x:.{d}f}"


def cov_cell(r):
    s = f"{100*r.coverage:.1f}\\,[{100*r.cov_lo:.1f},{100*r.cov_hi:.1f}]"
    return s if r.valid == 1 else s + "$^\\dagger$"


def ratio_cell(r):
    if r.method == "ppipp":
        return "1"
    return f"{r.ratio_vs_ppipp:.3f}\\,[{r.ratio_lo:.3f},{r.ratio_hi:.3f}]"


def body(df, label_of):
    lines = []
    for d, g in df.groupby("dataset", sort=True):
        ok = g[(g.valid == 1) & (g.method != "floor")]   # the floor is a bound, never a winner
        best = ok.width_mean.min() if len(ok) else np.nan
        first = True
        for _, r in g.iterrows():
            w = fnum(r.width_mean)
            if r.valid == 1 and r.method != "floor" and r.width_mean == best:
                w = f"\\textbf{{{w}}}"
            name = f"{esc(nice(d))} ($n$={int(r.n)})" if first else ""
            lines.append(f"{name} & {esc(label_of(r))} & {w} & {cov_cell(r)} & {ratio_cell(r)} \\\\")
            first = False
        lines.append("\\midrule")
    return lines[:-1]


def wrap(lines, cols="llrrr", head="Dataset & Method & Width & Coverage (\\%) [Wilson 95\\%] & Width / PPI++ [95\\% CI]"):
    return ["\\begin{tabular}{" + cols + "}", "\\toprule", head + " \\\\", "\\midrule", *lines, "\\bottomrule",
            "\\end{tabular}"]
